// Complex Nested Generics
// ============================================================================

class TokenRegistry[T] {
  private val registry = mutable.Map[String, TokenContainer[T]]()
  private val handlers = mutable.ListBuffer[T => Option[Token]]()

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry(key) = container
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers += handler
  }

  def process(key: String): Seq[Option[Token]] = {
    registry.get(key) match {
      case None => Seq.empty
      case Some(container) =>
        container.getAll.map { item =>
          // Find first handler that returns Some
          handlers.iterator.map(h => h(item)).find(_.isDefined).flatten
        }
    }
  }
}

