    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split("\\.")

    // Use Circe's cursor to navigate
    val cursor = value.hcursor

    val resultCursor = parts.foldLeft(cursor) { (current, part) =>
      // Check if part is an index (integer) or a field name
      // This is a simplified logic compared to Python's manual traversal,
      // leveraging Circe's flexibility if we assume standard JSON paths.
      // Python code checks if it's a list and part is digit.

      // In Circe, downField works for objects. downN works for arrays.
      // We need to guess or try both?
      // Python: 
      // if isinstance(current, dict) and part in current: current = current[part]
      // elif isinstance(current, list) and part.isdigit(): ...

      // Since we don't know the type of 'current' easily without inspection (which Cursor does internally)
      // we can try to treat part as index if it looks like one.

      if (part.forall(_.isDigit)) {
         current.downN(part.toInt)
      } else {
         current.downField(part)
      }
    }

    resultCursor.focus.map(tokenize)
  }
}

