  private val IsoFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val DateFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  override def tokenize(value: Either[LocalDateTime, LocalDate]): Token = {
    val (formatted, defaultFmt) = value match {
      case Left(dt) => (dt, IsoFormat)
      case Right(d) => (d, DateFormat)
    }

    val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(defaultFmt)

    val strValue = value match {
        case Left(dt) => dt.format(fmt)
        case Right(d) => d.format(fmt)
    }

    Token(strValue, TokenType.TEMPORAL)
  }

  def tokenize(value: LocalDateTime): Token = tokenize(Left(value))
  def tokenize(value: LocalDate): Token = tokenize(Right(value))
}

// ============================================================================ 
// Advanced: Union Types and Overloads
// ============================================================================ 

class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: String): Token = stringTokenizer.tokenize(value)
  def tokenize(value: Array[Byte]): Token = stringTokenizer.tokenize(value)

  def tokenize(value: Int): Token = numericTokenizer.tokenize(value)
  def tokenize(value: Double): Token = numericTokenizer.tokenize(value)
  def tokenize(value: BigDecimal): Token = numericTokenizer.tokenize(value)

  def tokenize(value: LocalDateTime): Token = temporalTokenizer.tokenize(value)
  def tokenize(value: LocalDate): Token = temporalTokenizer.tokenize(value)

  def tokenizeNull: Token = Token("NULL", TokenType.NULL)

  def tokenize(value: Tokenizable): Token = Token(value.toToken, TokenType.STRUCTURED)

  // Runtime dispatch
  def tokenize(value: Any): Token = value match {
    case null => tokenizeNull
    case t: Tokenizable => tokenize(t)
    case s: String => tokenize(s)
    case b: Array[Byte] => tokenize(b)
    case i: Int => tokenize(i)
    case d: Double => tokenize(d)
    case bd: BigDecimal => tokenize(bd)
    case dt: LocalDateTime => tokenize(dt)
    case d: LocalDate => tokenize(d)
    case other => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

// ============================================================================ 
// Complex Nested Generics
// ============================================================================ 

class TokenRegistry[T] {
  private val registry = mutable.Map[String, TokenContainer[T]]()
  private val handlers = mutable.ListBuffer[T => Option[Token]]()

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry(key) = container
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers += handler
  }

  def process(key: String): Seq[Option[Token]] = {
    registry.get(key) match {
      case None => Seq.empty
      case Some(container) =>
        container.getAll.map {
          item =>
          // Find first handler that returns Some
          handlers.iterator.map(h => h(item)).find(_.isDefined).flatten
        }
    }
  }
}

// ============================================================================ 
// Higher-Kinded Type Simulation
// ============================================================================ 

class TokenFunctor[T](private val _value: T) {
  def map[U](func: T => U): TokenFunctor[U] = {
    new TokenFunctor(func(_value))
  }

  def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] = {
    func(_value)
  }

  def getOrElse(default: T): T = {
    if (_value != null) _value else default
  }

  def get: T = _value
}

class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] = {
    new TokenMonad(funcWrapped.get(this.get))
  }
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================ 
// JSON Structure Tokenization
// ============================================================================ 

class JsonTokenizer(pretty: Boolean = false) {

  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split("\\.")

    // Use Circe's cursor to navigate
    val cursor: io.circe.ACursor = value.hcursor

    val resultCursor = parts.foldLeft(cursor) { (current, part) =>
      // Check if part is an index (integer) or a field name
      // This is a simplified logic compared to Python's manual traversal,
      // leveraging Circe's flexibility if we assume standard JSON paths.
      // Python code checks if it's a list and part is digit.

      // In Circe, downField works for objects. downN works for arrays.
      // We need to guess or try both?
      // Python: 
      // if isinstance(current, dict) and part in current: current = current[part]
      // elif isinstance(current, list) and part.isdigit(): ...

      // Since we don't know the type of 'current' easily without inspection (which Cursor does internally)
      // we can try to treat part as index if it looks like one.

      if (part.forall(_.isDigit)) {
         current.downN(part.toInt)
      } else {
         current.downField(part)
      }
    }

    resultCursor.focus.map(tokenize)
  }
}

// ============================================================================ 
// Whitespace Tokenizer
// ============================================================================ 

class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
       // Strip leading/trailing punctuation
       // Scala doesn't have a direct strip(chars) like Python.
       // We'll drop while in set.
       processed = processed.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) return None

    if (maxLength.isDefined && processed.length > maxLength.get) {
      processed = processed.substring(0, maxLength.get)
    }

    if (processed.isEmpty) None else Some(processed)
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+") // split by whitespace
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map {
        processed =>
        Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
      }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] = {
    tokenize(text).map(_.value)
  }

  def countTokens(text: String): Int = {
    tokenize(text).size
  }
}

// ============================================================================ 
// Builder Pattern
// ============================================================================ 

class TokenizerBuilder[T] {
  private val normalizers = mutable.ListBuffer[String => String]()
  private val validators = mutable.ListBuffer[T => Boolean]()
  private val metadata = mutable.Map[String, Any]()

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(meta: (String, Any)*): TokenizerBuilder[T] = {
    metadata ++= meta
    this
  }

  def build(): T => Token = {
    val finalNormalizers = normalizers.toList
    val finalValidators = validators.toList
    val finalMetadata = metadata.toMap

    (value: T) => {
      // Validate
      for (validator <- finalValidators) {
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      // Convert to string
      var strValue = value.toString

      // Normalize
      for (normalizer <- finalNormalizers) {
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.STRING, finalMetadata)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}
